// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {L1Block} from "../src/L1Block.sol";

contract InvMutTest is Test {
    L1Block c;
    function setUp() public { c = new L1Block(); }

    function testFuzz_property(uint256 seed, address actor) public {
        vm.assume(actor != address(0));
        // drive the boundary call through version()
        bool ok;
        string memory v;
        vm.prank(actor);
        try c.version() returns (string memory s) {
            ok = true;
            v = s;
        } catch {
            ok = false;
        }
        // Rule: for every admissible input, version() completes and reports "1.0.0"
        assertTrue(ok && keccak256(bytes(v)) == keccak256(bytes("1.0.0")));
    }
}
